WITH base AS (SELECT *, discount + shipping_fee discount_plus_shipping_fee FROM orders WHERE shipping_fee <= 18 AND order_date >= DATE '2023-06-03') SELECT id, store_id, order_date, channel, amount, ROUND(amount / SUM(amount) OVER (PARTITION BY customer_id), 4) amount_share, AVG(discount_plus_shipping_fee) OVER (PARTITION BY store_id) store_id_avg_discount_plus_shipping_fee, CORR(discount, shipping_fee) OVER (PARTITION BY store_id) corr_discount_shipping_fee FROM base;
